UPDATE public.exam_questions SET grammar_hint = $g001h${"tense_tr": "Dağıtıcı Belirleyiciler (Distributive Determiners)", "structure_tr": "boşluk + \"of the two finalists\" + tekil fiil (delivered)", "blank_type_tr": "iki üyeli bir grubu teker teker ele alan belirleyici", "reasoning_tr": "İki kişilik bir grubun üyelerini ayrı ayrı vurgulayan ve \"of\" ile kullanılabilen bir belirleyici aranmalı."}$g001h$::jsonb WHERE id = 'bbb92954-4b66-4dee-aa88-afcbdf36b521';
