UPDATE public.exam_questions SET grammar_hint = $h041h${"tense_tr": "So/Neither ile Katılma İfadesi - Olumsuz", "structure_tr": "bağlaç + yardımcı fiil + özne (devrik, önceki cümleyle aynı yardımcı fiil)", "blank_type_tr": "önceki olumsuz cümleyle aynı durumda olmayı bildiren devrik yapı", "reasoning_tr": "Önceki cümle olumsuz olduğu ve çoğul bir özne söz konusu olduğu için uyumlu yardımcı fiille kurulan olumsuz bir katılma yapısı gerekir."}$h041h$::jsonb WHERE id = '5db69310-5c47-4b19-b483-7229821f1ca0';
