UPDATE public.exam_questions SET grammar_hint = $h043h${"tense_tr": "Sonuç Cümleciği Yapısı (Derece Belirteci + Sıfat/İsim) - İstisna Kural", "structure_tr": "istisna yapı + many + çoğul isim", "blank_type_tr": "'many + çoğul isim' ile kullanılan istisnai derece belirteci", "reasoning_tr": "'many' bir miktar belirteci olup ardından çoğul sayılabilir bir isim geldiğinde standart kuralın dışına çıkılan özel bir istisna uygulanır."}$h043h$::jsonb WHERE id = '8e6ed1b8-10f6-4ec3-8e5f-dd1ffb325ef2';
UPDATE public.exam_questions SET grammar_hint = $h044h${"tense_tr": "Some/Any Kullanımı - Teklif/Rica", "structure_tr": "soru formunda teklif/rica cümlesinde kullanılan belirteç", "blank_type_tr": "soru formundaki teklif cümlesinde kullanılan olumlu belirteç", "reasoning_tr": "Cümle soru formunda olsa da aslında bir teklif/rica anlamı taşıdığı ve olumlu bir cevap beklendiği için istisnai olarak olumlu bağlamda kullanılan bir belirteç gerekir."}$h044h$::jsonb WHERE id = '35dc11c2-02f3-4fa6-b513-57891bff6138';
UPDATE public.exam_questions SET grammar_hint = $h045h${"tense_tr": "Some/Any Kullanımı - Olumsuz Cümle", "structure_tr": "olumsuz fiil + belirteç + isim (çifte olumsuzluktan kaçınma)", "blank_type_tr": "olumsuz cümlede kullanılan, çifte olumsuzluk yaratmayan belirteç", "reasoning_tr": "Cümle zaten olumsuz bir yardımcı fiille kurulduğu için cümleyi çifte olumsuz yapacak bir belirteç değil, olumsuz cümlelerle uyumlu bir belirteç gerekir."}$h045h$::jsonb WHERE id = '8e63b6b2-68aa-4a70-9d59-db7216978148';
UPDATE public.exam_questions SET grammar_hint = $h046h${"tense_tr": "Özne-Yüklem Uyumu (As well as)", "structure_tr": "asıl tekil özne + ... + tekil fiil (araya giren ifade göz ardı edilir)", "blank_type_tr": "asıl özneye göre çekimlenen, araya giren ifadeden etkilenmeyen fiil", "reasoning_tr": "Asıl özne tekil olduğu ve araya giren ifade özneyi çoğullaştırmadığı için fiil asıl özneye göre tekil çekimlenmeli."}$h046h$::jsonb WHERE id = '61490482-bb94-4407-9ef8-94bc88141811';
UPDATE public.exam_questions SET grammar_hint = $h047h${"tense_tr": "Özne-Yüklem Uyumu (Yanıltıcı Çoğul Görünümlü İsim)", "structure_tr": "tekil anlamlı isim (-s ile bitse de) + tekil fiil", "blank_type_tr": "görünüşte çoğul ama anlamca tekil olan isimle uyumlu fiil", "reasoning_tr": "Özne -s ile bitse de aslında sayılamayan/tekil kabul edilen bir isim olduğu için fiil çoğul değil tekil çekimlenmeli."}$h047h$::jsonb WHERE id = 'dfda443a-84e5-4a4d-b768-92ff3533069e';
UPDATE public.exam_questions SET grammar_hint = $h048h${"tense_tr": "Artikel Kullanımı (Sabit Coğrafi İsimler)", "structure_tr": "belirli artikel + nehir/dağ silsilesi gibi özel coğrafi isim", "blank_type_tr": "sabit coğrafi isimlerle zorunlu kullanılan belirli artikel", "reasoning_tr": "Nehir isimleri gibi bazı özel coğrafi isimler İngilizcede her zaman aynı artikel ile kullanılan, ezberlenmesi gereken bir istisna oluşturur."}$h048h$::jsonb WHERE id = '349da2cc-19ae-493f-80d3-6a8ec807fe7e';
UPDATE public.exam_questions SET grammar_hint = $h049h${"tense_tr": "Artikel Kullanımı (İlk Bahsediş vs İkinci Bahsediş)", "structure_tr": "ikinci kez bahsedilen, artık bilinen isimle kullanılan artikel", "blank_type_tr": "önceden tanıtılmış, artık belirli hale gelmiş isimle kullanılan artikel", "reasoning_tr": "İsim ilk cümlede belirsiz bir şekilde tanıtılmış ve ikinci bahsedilişinde artık karşılıklı bilinen bir varlık haline geldiği için buna uygun bir artikel gerekir."}$h049h$::jsonb WHERE id = 'fca30816-1d89-49fc-8ecc-17a762184d46';
UPDATE public.exam_questions SET grammar_hint = $h050h${"tense_tr": "Zaman Cümlecikleri (After) + Gelecek Anlam", "structure_tr": "after + özne + has/have + V3 (will almadan)", "blank_type_tr": "ana cümledeki eylemden önce tamamlanmış olacak, will almayan zaman yapısı", "reasoning_tr": "'after' ile kurulan zaman cümleciğinde ana cümledeki eylemden önce tamamlanmış olacak bir eylem anlatıldığı ve zaman cümleciklerinde 'will' kullanılamadığı için buna uygun bir yapı gerekir."}$h050h$::jsonb WHERE id = '64d78564-6769-4172-b91e-b84b661f0cb4';
UPDATE public.exam_questions SET grammar_hint = $h051h${"tense_tr": "Zaman Cümlecikleri (Until) + Gelecek Anlam", "structure_tr": "until + özne + yalın/3. tekil fiil (will almadan)", "blank_type_tr": "gelecekte gerçekleşecek olsa bile will almayan, zaman cümleciğine özgü fiil biçimi", "reasoning_tr": "'until' ile kurulan bir zaman cümleciği olduğu için olay gelecekte gerçekleşecek olsa bile bu tür cümleciklerde 'will' kullanılamaz."}$h051h$::jsonb WHERE id = 'bb5245f5-2207-4dd2-b5af-ae443b70e9af';
UPDATE public.exam_questions SET grammar_hint = $h052h${"tense_tr": "Used To (Geçmiş Alışkanlık)", "structure_tr": "used to + yalın fiil", "blank_type_tr": "artık geçerli olmayan geçmiş alışkanlığı bildiren yapı", "reasoning_tr": "Cümle otomasyon kurulmadan önce yapılıp artık yapılmayan bir geçmiş alışkanlığı anlattığı için buna uygun, sonrasında yalın fiil alan bir yapı gerekir."}$h052h$::jsonb WHERE id = '41574759-c277-493e-911a-28fd7892b493';
UPDATE public.exam_questions SET grammar_hint = $h053h${"tense_tr": "Be Used To (Şu Anki Alışkanlık)", "structure_tr": "be used to + fiil-ing", "blank_type_tr": "hâlâ devam eden, bir duruma alışkın olmayı bildiren -ing'li yapı", "reasoning_tr": "On yılı aşkın süredir bu duruma hâlâ alışkın olunduğu anlatıldığı için artık geçerli olmayan bir geçmiş alışkanlık değil, devam eden bir alışkınlık bildiren yapı gerekir."}$h053h$::jsonb WHERE id = '6ebd2dd2-911d-4d40-916e-5e7f1d9266c2';
