UPDATE public.exam_questions SET grammar_hint = $h055h${"tense_tr": "Remember + -ing (Geçmiş Eylemi Hatırlama)", "structure_tr": "remember + fiil-ing", "blank_type_tr": "daha önce gerçekleşmiş bir eylemi hatırlamayı bildiren -ing yapısı", "reasoning_tr": "Mert'in geçmişte zaten yaptığı bir eylemi hatırladığı anlatıldığı için henüz yapılmamış bir görevi hatırlamayı anlatan farklı bir yapı değil, geçmiş eylemi bildiren bir tamamlayıcı gerekir."}$h055h$::jsonb WHERE id = 'b067ddef-4522-489b-8f05-c6cd7a40ac71';
UPDATE public.exam_questions SET grammar_hint = $h056h${"tense_tr": "Fiil + That-Cümleciği (İstisnai Kalıp)", "structure_tr": "fiil + that + özne + yalın fiil (should düşmüş)", "blank_type_tr": "nesne+to-infinitive değil, doğrudan that-cümleciği alan istisnai fiil", "reasoning_tr": "Boşluktan sonra doğrudan bir that-cümleciği geldiği için nesne+to-infinitive kalıbı isteyen fiiller değil, bu kalıba uyan bir fiil gerekir."}$h056h$::jsonb WHERE id = '7a2b4583-8d0e-47ff-ac47-2592f9ab181e';
UPDATE public.exam_questions SET grammar_hint = $h057h${"tense_tr": "Fiil + Nesne + To-Infinitive", "structure_tr": "fiil + nesne + to + yalın fiil", "blank_type_tr": "nesneden sonra to-infinitive alan standart fiil tamamlayıcısı", "reasoning_tr": "Bu tür fiillerden sonra nesnenin mutlaka araya girmesi ve nesne ile to-infinitive arasına başka bir şey girmemesi gerektiği için buna uygun sözcük sırası gerekir."}$h057h$::jsonb WHERE id = 'da4ccdfc-1248-44b1-8f81-7669dc42c542';
UPDATE public.exam_questions SET grammar_hint = $h058h${"tense_tr": "Look Forward To + -ing (Edat + -ing)", "structure_tr": "... to (edat) + fiil-ing", "blank_type_tr": "edat olan 'to'dan sonra gelen -ing formu", "reasoning_tr": "Bu kalıptaki 'to' bir infinitive belirteci değil bir edat olduğu için ardından yalın fiil değil -ing formu gelmeli."}$h058h$::jsonb WHERE id = '0b629a05-8332-49a5-8760-7bb58315ba5c';
UPDATE public.exam_questions SET grammar_hint = $h059h${"tense_tr": "Be Opposed To + -ing (Edat + -ing)", "structure_tr": "... to (edat) + fiil-ing", "blank_type_tr": "edat olan 'to'dan sonra gelen -ing formu", "reasoning_tr": "Bu kalıptaki 'to' bir infinitive belirteci değil bir edat olduğu için ardından yalın fiil değil -ing formu gelmeli."}$h059h$::jsonb WHERE id = '132bec81-7ce8-41a3-b2de-2f6684fe8039';
