UPDATE public.exam_questions SET grammar_hint = $h062h${"tense_tr": "Kelime Türetme (Sıfattan/Fiilden İsim)", "structure_tr": "sıfat + isim (özne/nesne konumunda soyut isim)", "blank_type_tr": "özne/nesne konumunda kullanılabilen soyut isim", "reasoning_tr": "Boşluk bir sıfattan sonra özne/nesne görevinde bir isim konumunda olduğu için fiil veya sıfat değil isim biçimi gerekir."}$h062h$::jsonb WHERE id = '0be92425-2753-48ce-bbdf-194f54750554';
UPDATE public.exam_questions SET grammar_hint = $h063h${"tense_tr": "Collocation (Fiil-İsim Eşleşmesi)", "structure_tr": "yerleşik fiil + isim eşleşmesi", "blank_type_tr": "bu isimle doğal olarak eşleşen, ezberlenmesi gereken fiil", "reasoning_tr": "İngilizcede bu isimle birlikte kullanılan fiil bir gramer kuralından çok yerleşik bir eşleşme (collocation) olduğu için anlamca yakın ama bu isimle doğal eşleşmeyen fiiller burada uygun değildir."}$h063h$::jsonb WHERE id = 'e7583478-1b0b-4d3d-9b8c-3509c10543b0';

